//! The DittoBench v13 tool catalog — the seed-free PRODUCTION surface the
//! scored run advertises (per-seed coined decoys are added only on the scored
//! wire by the validator and are never part of this mirror). It intentionally
//! excludes the retired v7 workflow, automation, recipe, and job-status tools
//! and the v13-retired set_main_model, so local practice presents exactly the
//! product surface scored by the active benchmark.
//!
//! GENERATED by "go run ./cmd/catalogmirror -bench-version 13 -format rust"
//! (research/dittobench-datagen) from catalog.CatalogForVersion; regenerate
//! there instead of editing by hand, then run "cargo fmt".

use serde_json::{json, Value};

use crate::protocol::ToolDefWire;

#[derive(Clone, Copy)]
enum SchemaType {
    String,
    StringArray,
    Array,
    Integer,
    Boolean,
    /// A closed value list rendered as a JSON-schema enum (bench v13+).
    Enum(&'static [&'static str]),
}

#[derive(Clone, Copy)]
struct Prop {
    name: &'static str,
    kind: SchemaType,
    description: &'static str,
}

fn prop(name: &'static str, kind: SchemaType, description: &'static str) -> Prop {
    Prop {
        name,
        kind,
        description,
    }
}

fn schema(props: &[Prop], required: &[&str]) -> Value {
    let mut properties = serde_json::Map::new();
    for prop in props {
        let value = match prop.kind {
            SchemaType::String => {
                json!({"type": "string", "description": prop.description})
            }
            SchemaType::StringArray => json!({
                "type": "array",
                "items": {"type": "string"},
                "description": prop.description,
            }),
            SchemaType::Array => {
                json!({"type": "array", "description": prop.description})
            }
            SchemaType::Integer => {
                json!({"type": "integer", "description": prop.description})
            }
            SchemaType::Boolean => {
                json!({"type": "boolean", "description": prop.description})
            }
            SchemaType::Enum(values) => json!({
                "type": "string",
                "description": prop.description,
                "enum": values,
            }),
        };
        properties.insert(prop.name.to_string(), value);
    }
    let mut out = serde_json::Map::new();
    out.insert("type".to_string(), json!("object"));
    out.insert("properties".to_string(), Value::Object(properties));
    if !required.is_empty() {
        out.insert("required".to_string(), json!(required));
    }
    Value::Object(out)
}

fn strings(props: &[(&'static str, &'static str)], required: &[&str]) -> Value {
    let props = props
        .iter()
        .map(|(name, description)| prop(name, SchemaType::String, description))
        .collect::<Vec<_>>();
    schema(&props, required)
}

fn tool(name: &str, description: &str, parameters: Value) -> ToolDefWire {
    ToolDefWire {
        name: name.to_string(),
        description: description.to_string(),
        parameters,
    }
}

