#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_matches_active_v13_surface() {
        let catalog = catalog();
        assert_eq!(catalog.len(), 30);
        let names = catalog
            .iter()
            .map(|tool| tool.name.as_str())
            .collect::<Vec<_>>();
        assert_eq!(
            names,
            vec![
                "create_image",
                "edit_image",
                "read_links",
                "search_web",
                "search_memories",
                "search_subjects",
                "fetch_memories",
                "search_memories_in_subjects",
                "artifacts",
                "execute_agent_job",
                "run_code",
                "search_tools",
                "list_agent_jobs",
                "file_feedback_for_team",
                "set_theme",
                "set_reasoning_effort",
                "set_chat_tool_preferences",
                "discover_capabilities",
                "save_memory",
                "update_memory",
                "delete_memory",
                "calendar_create_event",
                "calendar_search_events",
                "gmail_send",
                "set_accent_color",
                "set_chat_font",
                "create_workflow",
                "list_workflows",
                "list_schedules",
                "run_workflow"
            ]
        );
    }

    #[test]
    fn catalog_uses_current_argument_shapes() {
        let catalog = catalog();
        let named = |name: &str| {
            catalog
                .iter()
                .find(|tool| tool.name == name)
                .unwrap_or_else(|| panic!("missing tool {name}"))
        };

        assert_eq!(
            named("read_links").parameters["properties"]["urls"]["type"],
            "array"
        );
        assert_eq!(
            named("search_web").parameters["properties"]["queries"]["type"],
            "array"
        );
        assert_eq!(
            named("fetch_memories").parameters["properties"]["pairIds"]["type"],
            "array"
        );
        assert_eq!(
            named("create_workflow").parameters["required"],
            json!(["name", "steps"])
        );
        assert_eq!(
            named("list_agent_jobs").parameters["properties"]["limit"]["type"],
            "integer"
        );
        assert_eq!(
            named("set_reasoning_effort").parameters["properties"]["effort"]["enum"],
            json!(["low", "medium", "high"])
        );
        assert_eq!(
            named("set_theme").parameters["properties"]["theme"]["enum"],
            json!(["system", "light", "dark", "midnight", "solarized"])
        );
        for retired in [
            "execute_agent_workflow",
            "get_agent_job_status",
            "create_automation",
            "list_automations",
            "create_recipe",
            "apply_recipe",
            "set_main_model",
        ] {
            assert!(
                catalog.iter().all(|tool| tool.name != retired),
                "catalog still advertises retired tool {retired}"
            );
        }
    }

    #[test]
    fn every_tool_has_an_object_schema() {
        for tool in catalog() {
            assert_eq!(tool.parameters["type"], "object", "tool {}", tool.name);
            assert!(
                tool.parameters.get("properties").is_some(),
                "tool {}",
                tool.name
            );
        }
    }
}
